package com.creedpdf.orbitalrailgun.registry;

import com.creedpdf.orbitalrailgun.RailgunMod;
import net.fabricmc.fabric.api.particle.v1.FabricParticleTypes;
import net.minecraft.particle.DefaultParticleType;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;

/**
 * Custom particle types. Their sprites are in assets/orbital_railgun/textures/particle/
 * (generated by tools/textures/build_textures.py) and their behaviour is defined client-side in
 * {@code RailgunParticle}. All are "always show" so the huge effects render at long range and on
 * reduced particle settings.
 */
public final class ModParticles {
    private ModParticles() {}

    public static final DefaultParticleType PLASMA_SPARK = register("plasma_spark");
    public static final DefaultParticleType ENERGY_MOTE = register("energy_mote");
    public static final DefaultParticleType PLASMA_SMOKE = register("plasma_smoke");
    public static final DefaultParticleType REENTRY_FIRE = register("reentry_fire");
    public static final DefaultParticleType EMBER = register("ember");
    public static final DefaultParticleType DEBRIS = register("debris");
    public static final DefaultParticleType FLASH = register("flash");
    public static final DefaultParticleType SHOCK_DUST = register("shock_dust");

    private static DefaultParticleType register(String name) {
        return Registry.register(Registries.PARTICLE_TYPE, RailgunMod.id(name), FabricParticleTypes.simple(true));
    }

    public static void init() {}
}
